diffs.patch:
diff --git a/src/clone.js b/src/clone.js
index ff24a42..b8d4067 100644
--- a/src/clone.js
+++ b/src/clone.js
@@ -1,9 +1,11 @@
-export function deepClone(obj) {
+export function deepClone(obj, seen = new WeakSet(), clones = new WeakMap()) {
   if (obj === null || typeof obj !== 'object') return obj;
-  if (Array.isArray(obj)) return obj.map(item => deepClone(item));
-  const clone = {};
+  if (seen.has(obj)) return clones.get(obj);
+  seen.add(obj);
+  const clone = Array.isArray(obj) ? [] : {};
+  clones.set(obj, clone);
   for (const key of Object.keys(obj)) {
-    clone[key] = deepClone(obj[key]);
+    clone[key] = deepClone(obj[key], seen, clones);
   }
   return clone;
 }
